mapper.select:
select jt.*, e1.name as emp_name, e2.name as approver_name, d.name as target_dept_name from job_transfer jt left join emp e1 on jt.emp_id = e1.id left join emp e2 on jt.approver_id = e2.id left join dept d on jt.target_dept_id = d.id
jt.status = #{status}
order by jt.create_time desc, jt.id desc limit #{offset}, #{pageSize}
